-- Tools and harvest nodes (#37 stage 5). The engine knew Classic's tools by name: an "Axe" swung on
-- Axe Fighting's ladder, a "Mining" tool on Mining's, a "Fishing" weapon waited 20, and each
-- gathering tool row named its tile, while the Mining Hammer's ore roll, the hammers' chunks and the
-- shovel's diggable grounds were read by the tool's name. Content now says it: item-rules.json
-- `tools` (what a tool can do, its tier and its swing ladder), `ladders` and `requires`; gather.json
-- `harvest` (what a tile becomes under a tool) and `yields` (what a success drops). The bindings
-- `axeFighting` and `mining` go: the ladders name their skills.
--
-- What the old engine did is worked out from the gathering and skill bindings in effect at each
-- layer: the packs (the last imported pack with each section, over Classic), then the operator's
-- rows, then the draft.
-- - Imported packs: a pack's own gathering becomes its harvest nodes and yields (a "=" tool works
--   only its own tile; a chunk sharing an item with another drop is keyed `item (tool)`). A pack's
--   datasets are whole, so every pack with item rules gets the tools and ladders the packs' merged
--   gathering and bindings imply (ladders read the bound skills, and are left out where unbound).
-- - The operator layer gets a row for each new section that comes out differently from the packs'
--   (a pack's gathering with no item rules of its own lands here too), and the draft one for each
--   that comes out differently from the operator layer: a draft that reverted the gathering or the
--   bindings reverts what was taken from them.
-- - Each publish that changed the gathering or the bindings gains entries for the sections taken
--   from them, so undoing it still undoes the change; the old fields leave its rows.
-- A row the migration makes records the packs' section as its base (its hash is worked out when
-- read). It runs once: run again by hand after it is recorded, it changes nothing.
-- What it cannot express: an old pack's second "contains" tool on a tile another "contains" tool
-- already worked now works that one's node (Classic has none).
--
-- Generated by a script from the Classic content at the time; the literals are Classic's old
-- gathering fields and its new sections.

CREATE TEMP TABLE classic_64 (g TEXT, b TEXT, s TEXT, tools TEXT, ladders TEXT, harvest TEXT, yields TEXT);
INSERT INTO classic_64 VALUES ('{"tools":[{"tool":"Axe","match":"contains","counter":"Chop","skill":"Lumberjacking","tiles":{"from":"S3","to":"P3"},"successSound":{"name":"treefalling","ch":2},"hitSound":{"name":"treechop","ch":3},"imp":"LumberjackImp"},{"tool":"Shovel","match":"=","counter":"Dig","skill":"Shoveling","tiles":{"from":"G3","to":"1K"},"successSound":{"name":"shoveling","ch":2},"hitSound":null,"imp":"ShovelingImp"},{"tool":"Hoe","match":"=","counter":"Farm","skill":"Farming","tiles":{"from":"TL","to":"SL"},"successSound":{"name":"shoveling","ch":2},"hitSound":null,"imp":"FarmingImp"},{"tool":"Watering Bucket","match":"=","counter":"Watering","skill":"Farming","successSound":null,"hitSound":null,"imp":null},{"tool":"Mining Hammer","match":"=","counter":"Mine","skill":"Mining","tiles":{"from":"B8","to":"O8"},"successSound":{"name":"crush","ch":2},"hitSound":{"name":"swordhit2","ch":3},"imp":"MiningImp"},{"tool":"Ice Hammer","match":"=","counter":"Mine","skill":"Mining","tiles":{"from":"1G","to":"0Z"},"successSound":{"name":"crush","ch":2},"hitSound":{"name":"swordhit2","ch":3},"imp":"MiningImp"},{"tool":"Fire Hammer","match":"=","counter":"Mine","skill":"Mining","tiles":{"from":"6O","to":"6N"},"successSound":{"name":"crush","ch":2},"hitSound":{"name":"swordhit2","ch":3},"imp":"MiningImp"}],"logs":{"item":"Logs","chance":3},"shovelLayer1":{"test":"*G1*H1*O1"},"mining":{"chunks":[{"tool":"Ice Hammer","item":"Chunk of Ice","chance":130},{"tool":"Fire Hammer","item":"Chunk of Fire","chance":130}]},"fishing":{"tool":"Fishing","atDelay":20}}', '{"axeFighting":"AxeFighting","mining":"Mining"}', '[{"handler":"LumberjackImp","skill":"Lumberjacking","chance":12,"min":0,"below":100,"text":"You have advanced in the art of Lumberjacking!"},{"handler":"ShovelingImp","skill":"Shoveling","chance":12,"min":0,"below":100,"text":"You have advanced in the art of Shoveling!"},{"handler":"FarmingImp","skill":"Farming","chance":12,"min":0,"below":100,"text":"You have advanced in the art of Farming!"},{"handler":"MiningImp","skill":"Mining","chance":22,"min":0,"below":100,"text":"You have advanced in the art of Mining!"},{"handler":"FishingImp","skill":"Fishing","chance":16,"min":0,"below":100,"text":"You have advanced in the art of Fishing!"},{"handler":"CookImp","skill":"Cooking","chance":8,"min":0,"below":100,"text":"You have advanced in the art of Cooking!"},{"handler":"SmithImp","skill":"Blacksmithing","chance":9,"min":0,"below":100,"text":"You have advanced in the art of Blacksmithing!"},{"handler":"AlchemyImp","skill":"Alchemy","chance":15,"min":0,"below":100,"text":"You have advanced in the art of Alchemy!"},{"handler":"CarpentryImp","skill":"Carpentry","chance":9,"min":0,"below":100,"text":"You have advanced in the art of Carpentry!"}]', '[{"match":"contains","pattern":"Axe","can":"Chop"},{"match":"exact","pattern":"Shovel","can":"Dig"},{"match":"exact","pattern":"Hoe","can":"Farm"},{"match":"exact","pattern":"Watering Bucket","can":"Water"},{"match":"exact","pattern":"Mining Hammer","can":"Mine"},{"match":"exact","pattern":"Ice Hammer","can":"Mine"},{"match":"exact","pattern":"Fire Hammer","can":"Mine"},{"match":"contains","pattern":"Fishing","can":"Fish"},{"match":"contains","pattern":"Axe","ladder":"axe"},{"match":"contains","pattern":"Mining","ladder":"mining"},{"match":"contains","pattern":"Fishing","ladder":"fishing"}]', '{"axe":{"skill":"AxeFighting","steps":[{"below":10,"delay":25},{"below":20,"delay":22},{"below":30,"delay":21},{"below":40,"delay":20},{"below":50,"delay":19},{"below":60,"delay":18},{"below":70,"delay":17},{"below":80,"delay":16},{"below":90,"delay":15}]},"mining":{"skill":"Mining","steps":[{"below":10,"delay":15},{"below":20,"delay":14},{"below":30,"delay":13},{"below":40,"delay":12},{"below":50,"delay":11},{"below":60,"delay":10},{"below":70,"delay":9},{"below":80,"delay":8},{"delay":7}]},"fishing":{"steps":[{"delay":20}],"gearSpeedUp":true}}', '[{"tile":"G3","can":"Dig","tools":["Shovel"],"under":["G1","H1","O1"],"becomes":"1K","skill":"Shoveling","gains":true,"treasure":true,"hitSound":null,"successSound":{"name":"shoveling","ch":2}},{"tile":"TL","can":"Farm","tools":["Hoe"],"becomes":"SL","skill":"Farming","gains":true,"hitSound":null,"successSound":{"name":"shoveling","ch":2}},{"tile":"B8","can":"Mine","tools":["Mining Hammer"],"becomes":"O8","skill":"Mining","gains":true,"yield":"Mining","hitSound":{"name":"swordhit2","ch":3},"successSound":{"name":"crush","ch":2}},{"tile":"1G","can":"Mine","tools":["Ice Hammer"],"becomes":"0Z","skill":"Mining","gains":true,"yield":"Chunk of Ice","hitSound":{"name":"swordhit2","ch":3},"successSound":{"name":"crush","ch":2}},{"tile":"6O","can":"Mine","tools":["Fire Hammer"],"becomes":"6N","skill":"Mining","gains":true,"yield":"Chunk of Fire","hitSound":{"name":"swordhit2","ch":3},"successSound":{"name":"crush","ch":2}},{"tile":"S3","can":"Chop","becomes":"P3","skill":"Lumberjacking","gains":true,"yield":"Logs","hitSound":{"name":"treechop","ch":3},"successSound":{"name":"treefalling","ch":2}}]', '{"Logs":{"kind":"chance","item":"Logs","chance":3},"Mining":{"kind":"ore"},"Chunk of Ice":{"kind":"chance","item":"Chunk of Ice","chance":130},"Chunk of Fire":{"kind":"chance","item":"Chunk of Fire","chance":130}}');

CREATE TEMP TABLE eff_64 (
  pack_g TEXT, pack_b TEXT, pack_s TEXT, has_rules INTEGER, has_gather INTEGER,
  op_g TEXT, op_b TEXT, op_s TEXT, draft_g TEXT, draft_b TEXT, draft_s TEXT,
  mp_tools TEXT, mp_ladders TEXT, mp_harvest TEXT, mp_yields TEXT,
  op_tools TEXT, op_ladders TEXT, op_harvest TEXT, op_yields TEXT,
  dr_tools TEXT, dr_ladders TEXT, dr_harvest TEXT, dr_yields TEXT
);
INSERT INTO eff_64 (pack_g, pack_b, pack_s, has_rules, has_gather)
SELECT
  coalesce((SELECT json_extract(data, '$.data.gather.gathering') FROM content_packs
    WHERE source = 'imported' AND json_type(data, '$.data.gather.gathering.tools') = 'array'
    ORDER BY position DESC, id DESC LIMIT 1), c.g),
  coalesce((SELECT json_extract(data, '$.data.bindings.skills') FROM content_packs
    WHERE source = 'imported' AND json_type(data, '$.data.bindings.skills') = 'object'
    ORDER BY position DESC, id DESC LIMIT 1), c.b),
  coalesce((SELECT json_extract(data, '$.data.gather.skillGain') FROM content_packs
    WHERE source = 'imported' AND json_type(data, '$.data.gather.skillGain') = 'array'
    ORDER BY position DESC, id DESC LIMIT 1), c.s),
  EXISTS (SELECT 1 FROM content_packs WHERE source = 'imported' AND json_type(data, '$.data."item-rules"') = 'object'),
  EXISTS (SELECT 1 FROM content_packs WHERE source = 'imported' AND json_type(data, '$.data.gather.gathering.tools') = 'array')
FROM classic_64 c
WHERE NOT EXISTS (SELECT 1 FROM _migrations WHERE name = '20261123_64_tools_and_harvest.sql');

UPDATE eff_64 SET
  op_g = coalesce((SELECT data FROM content_rows WHERE dataset = 'gather' AND part = 'gathering' AND op = 'set' AND json_type(data, '$.tools') = 'array'), pack_g),
  op_b = coalesce((SELECT data FROM content_rows WHERE dataset = 'bindings' AND part = 'skills' AND op = 'set' AND json_type(data) = 'object'), pack_b),
  op_s = coalesce((SELECT data FROM content_rows WHERE dataset = 'gather' AND part = 'skillGain' AND op = 'set' AND json_type(data) = 'array'), pack_s);
UPDATE eff_64 SET
  draft_g = coalesce((SELECT CASE op WHEN 'revert' THEN pack_g ELSE data END FROM content_draft
    WHERE dataset = 'gather' AND part = 'gathering' AND (op = 'revert' OR (op = 'set' AND json_type(data, '$.tools') = 'array'))), op_g),
  draft_b = coalesce((SELECT CASE op WHEN 'revert' THEN pack_b ELSE data END FROM content_draft
    WHERE dataset = 'bindings' AND part = 'skills' AND (op = 'revert' OR (op = 'set' AND json_type(data) = 'object'))), op_b),
  draft_s = coalesce((SELECT CASE op WHEN 'revert' THEN pack_s ELSE data END FROM content_draft
    WHERE dataset = 'gather' AND part = 'skillGain' AND (op = 'revert' OR (op = 'set' AND json_type(data) = 'array'))), op_s);
UPDATE eff_64 SET
  mp_tools = json(CASE WHEN has_rules THEN json_insert(CASE WHEN json_type(pack_b, '$.mining') = 'text' THEN json_insert(CASE WHEN json_type(pack_b, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(pack_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(pack_g, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(pack_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(pack_g, '$.fishing.tool'), 'can', 'Fish')) END, '$[#]', json('{"match":"contains","pattern":"Mining","ladder":"mining"}')) ELSE CASE WHEN json_type(pack_b, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(pack_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(pack_g, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(pack_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(pack_g, '$.fishing.tool'), 'can', 'Fish')) END END, '$[#]', json('{"match":"contains","pattern":"Fishing","ladder":"fishing"}')) ELSE (SELECT tools FROM classic_64) END),
  mp_ladders = json(CASE WHEN has_rules THEN json_patch('{}', json_object(
      'axe', CASE WHEN json_type(pack_b, '$.axeFighting') = 'text' THEN json_object('skill', json_extract(pack_b, '$.axeFighting'), 'steps', json('[{"below":10,"delay":25},{"below":20,"delay":22},{"below":30,"delay":21},{"below":40,"delay":20},{"below":50,"delay":19},{"below":60,"delay":18},{"below":70,"delay":17},{"below":80,"delay":16},{"below":90,"delay":15}]')) END,
      'mining', CASE WHEN json_type(pack_b, '$.mining') = 'text' THEN json_object('skill', json_extract(pack_b, '$.mining'), 'steps', json('[{"below":10,"delay":15},{"below":20,"delay":14},{"below":30,"delay":13},{"below":40,"delay":12},{"below":50,"delay":11},{"below":60,"delay":10},{"below":70,"delay":9},{"below":80,"delay":8},{"delay":7}]')) END,
      'fishing', json_object('steps', json_array(json_object('delay', min(max(json_extract(pack_g, '$.fishing.atDelay'), 1), 1000))), 'gearSpeedUp', json('true')))) ELSE (SELECT ladders FROM classic_64) END),
  mp_harvest = json(CASE WHEN has_gather THEN (SELECT coalesce(json_group_array(json(n.node)), '[]') FROM (SELECT json_set(json_set(json_patch('{}', json_object(
      'tile', json_extract(t.value, '$.tiles.from'),
      'can', json_extract(t.value, '$.counter'),
      'tools', CASE WHEN json_extract(t.value, '$.match') = '=' THEN json_array(json_extract(t.value, '$.tool')) END,
      'under', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json((SELECT json_group_array(u.value) FROM json_each('["' || replace(replace(replace(json_extract(pack_g, '$.shovelLayer1.test'), char(92), ''), '"', ''), '*', '","') || '"]') u
      WHERE length(u.value) = 2)) END,
      'becomes', json_extract(t.value, '$.tiles.to'),
      'skill', json_extract(t.value, '$.skill'),
      'gains', json(CASE WHEN json_type(t.value, '$.imp') = 'text' AND EXISTS (SELECT 1 FROM json_each(pack_s) r
        WHERE lower(replace(json_extract(r.value, '$.skill'), ' ', '')) = lower(replace(json_extract(t.value, '$.skill'), ' ', ''))) THEN 'true' ELSE 'false' END),
      'yield', CASE json_extract(t.value, '$.counter')
        WHEN 'Chop' THEN json_extract(pack_g, '$.logs.item')
        WHEN 'Mine' THEN CASE WHEN lower(json_extract(t.value, '$.tool')) = 'mining hammer' THEN 'Mining'
          ELSE (SELECT (CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(pack_g, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(pack_g, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END) FROM json_each(pack_g, '$.mining.chunks') c
                WHERE lower(json_extract(c.value, '$.tool')) = lower(json_extract(t.value, '$.tool')) ORDER BY c.key LIMIT 1) END
      END,
      'treasure', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json('true') END
    )), '$.hitSound', json(json_extract(t.value, '$.hitSound'))), '$.successSound', json(json_extract(t.value, '$.successSound'))) AS node
    FROM json_each(pack_g, '$.tools') t
    WHERE json_extract(t.value, '$.counter') <> 'Watering' AND json_type(t.value, '$.tiles') = 'object'
      AND NOT (json_extract(t.value, '$.match') <> '=' AND EXISTS (SELECT 1 FROM json_each(pack_g, '$.tools') o
        WHERE o.key < t.key AND json_extract(o.value, '$.match') <> '='
          AND json_extract(o.value, '$.counter') = json_extract(t.value, '$.counter')
          AND lower(json_extract(o.value, '$.tiles.from')) = lower(json_extract(t.value, '$.tiles.from'))))
    ORDER BY json_extract(t.value, '$.match') <> '=', t.key) n) ELSE (SELECT harvest FROM classic_64) END),
  mp_yields = json(CASE WHEN has_gather THEN json_patch(json_object(
      json_extract(pack_g, '$.logs.item'), json_object('kind', 'chance', 'item', json_extract(pack_g, '$.logs.item'), 'chance', json_extract(pack_g, '$.logs.chance')),
      'Mining', json_object('kind', 'ore')),
    coalesce((SELECT json_group_object((CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(pack_g, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(pack_g, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END), json_object('kind', 'chance', 'item', json_extract(c.value, '$.item'), 'chance', json_extract(c.value, '$.chance')))
      FROM (SELECT key, value FROM json_each(pack_g, '$.mining.chunks') ORDER BY key) c), '{}')) ELSE (SELECT yields FROM classic_64) END),
  op_tools = json(json_insert(CASE WHEN json_type(op_b, '$.mining') = 'text' THEN json_insert(CASE WHEN json_type(op_b, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(op_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(op_g, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(op_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(op_g, '$.fishing.tool'), 'can', 'Fish')) END, '$[#]', json('{"match":"contains","pattern":"Mining","ladder":"mining"}')) ELSE CASE WHEN json_type(op_b, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(op_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(op_g, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(op_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(op_g, '$.fishing.tool'), 'can', 'Fish')) END END, '$[#]', json('{"match":"contains","pattern":"Fishing","ladder":"fishing"}'))),
  op_ladders = json(json_patch('{}', json_object(
      'axe', CASE WHEN json_type(op_b, '$.axeFighting') = 'text' THEN json_object('skill', json_extract(op_b, '$.axeFighting'), 'steps', json('[{"below":10,"delay":25},{"below":20,"delay":22},{"below":30,"delay":21},{"below":40,"delay":20},{"below":50,"delay":19},{"below":60,"delay":18},{"below":70,"delay":17},{"below":80,"delay":16},{"below":90,"delay":15}]')) END,
      'mining', CASE WHEN json_type(op_b, '$.mining') = 'text' THEN json_object('skill', json_extract(op_b, '$.mining'), 'steps', json('[{"below":10,"delay":15},{"below":20,"delay":14},{"below":30,"delay":13},{"below":40,"delay":12},{"below":50,"delay":11},{"below":60,"delay":10},{"below":70,"delay":9},{"below":80,"delay":8},{"delay":7}]')) END,
      'fishing', json_object('steps', json_array(json_object('delay', min(max(json_extract(op_g, '$.fishing.atDelay'), 1), 1000))), 'gearSpeedUp', json('true'))))),
  op_harvest = json((SELECT coalesce(json_group_array(json(n.node)), '[]') FROM (SELECT json_set(json_set(json_patch('{}', json_object(
      'tile', json_extract(t.value, '$.tiles.from'),
      'can', json_extract(t.value, '$.counter'),
      'tools', CASE WHEN json_extract(t.value, '$.match') = '=' THEN json_array(json_extract(t.value, '$.tool')) END,
      'under', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json((SELECT json_group_array(u.value) FROM json_each('["' || replace(replace(replace(json_extract(op_g, '$.shovelLayer1.test'), char(92), ''), '"', ''), '*', '","') || '"]') u
      WHERE length(u.value) = 2)) END,
      'becomes', json_extract(t.value, '$.tiles.to'),
      'skill', json_extract(t.value, '$.skill'),
      'gains', json(CASE WHEN json_type(t.value, '$.imp') = 'text' AND EXISTS (SELECT 1 FROM json_each(op_s) r
        WHERE lower(replace(json_extract(r.value, '$.skill'), ' ', '')) = lower(replace(json_extract(t.value, '$.skill'), ' ', ''))) THEN 'true' ELSE 'false' END),
      'yield', CASE json_extract(t.value, '$.counter')
        WHEN 'Chop' THEN json_extract(op_g, '$.logs.item')
        WHEN 'Mine' THEN CASE WHEN lower(json_extract(t.value, '$.tool')) = 'mining hammer' THEN 'Mining'
          ELSE (SELECT (CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(op_g, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(op_g, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END) FROM json_each(op_g, '$.mining.chunks') c
                WHERE lower(json_extract(c.value, '$.tool')) = lower(json_extract(t.value, '$.tool')) ORDER BY c.key LIMIT 1) END
      END,
      'treasure', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json('true') END
    )), '$.hitSound', json(json_extract(t.value, '$.hitSound'))), '$.successSound', json(json_extract(t.value, '$.successSound'))) AS node
    FROM json_each(op_g, '$.tools') t
    WHERE json_extract(t.value, '$.counter') <> 'Watering' AND json_type(t.value, '$.tiles') = 'object'
      AND NOT (json_extract(t.value, '$.match') <> '=' AND EXISTS (SELECT 1 FROM json_each(op_g, '$.tools') o
        WHERE o.key < t.key AND json_extract(o.value, '$.match') <> '='
          AND json_extract(o.value, '$.counter') = json_extract(t.value, '$.counter')
          AND lower(json_extract(o.value, '$.tiles.from')) = lower(json_extract(t.value, '$.tiles.from'))))
    ORDER BY json_extract(t.value, '$.match') <> '=', t.key) n)),
  op_yields = json(json_patch(json_object(
      json_extract(op_g, '$.logs.item'), json_object('kind', 'chance', 'item', json_extract(op_g, '$.logs.item'), 'chance', json_extract(op_g, '$.logs.chance')),
      'Mining', json_object('kind', 'ore')),
    coalesce((SELECT json_group_object((CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(op_g, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(op_g, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END), json_object('kind', 'chance', 'item', json_extract(c.value, '$.item'), 'chance', json_extract(c.value, '$.chance')))
      FROM (SELECT key, value FROM json_each(op_g, '$.mining.chunks') ORDER BY key) c), '{}'))),
  dr_tools = json(json_insert(CASE WHEN json_type(draft_b, '$.mining') = 'text' THEN json_insert(CASE WHEN json_type(draft_b, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(draft_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(draft_g, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(draft_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(draft_g, '$.fishing.tool'), 'can', 'Fish')) END, '$[#]', json('{"match":"contains","pattern":"Mining","ladder":"mining"}')) ELSE CASE WHEN json_type(draft_b, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(draft_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(draft_g, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(draft_g, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(draft_g, '$.fishing.tool'), 'can', 'Fish')) END END, '$[#]', json('{"match":"contains","pattern":"Fishing","ladder":"fishing"}'))),
  dr_ladders = json(json_patch('{}', json_object(
      'axe', CASE WHEN json_type(draft_b, '$.axeFighting') = 'text' THEN json_object('skill', json_extract(draft_b, '$.axeFighting'), 'steps', json('[{"below":10,"delay":25},{"below":20,"delay":22},{"below":30,"delay":21},{"below":40,"delay":20},{"below":50,"delay":19},{"below":60,"delay":18},{"below":70,"delay":17},{"below":80,"delay":16},{"below":90,"delay":15}]')) END,
      'mining', CASE WHEN json_type(draft_b, '$.mining') = 'text' THEN json_object('skill', json_extract(draft_b, '$.mining'), 'steps', json('[{"below":10,"delay":15},{"below":20,"delay":14},{"below":30,"delay":13},{"below":40,"delay":12},{"below":50,"delay":11},{"below":60,"delay":10},{"below":70,"delay":9},{"below":80,"delay":8},{"delay":7}]')) END,
      'fishing', json_object('steps', json_array(json_object('delay', min(max(json_extract(draft_g, '$.fishing.atDelay'), 1), 1000))), 'gearSpeedUp', json('true'))))),
  dr_harvest = json((SELECT coalesce(json_group_array(json(n.node)), '[]') FROM (SELECT json_set(json_set(json_patch('{}', json_object(
      'tile', json_extract(t.value, '$.tiles.from'),
      'can', json_extract(t.value, '$.counter'),
      'tools', CASE WHEN json_extract(t.value, '$.match') = '=' THEN json_array(json_extract(t.value, '$.tool')) END,
      'under', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json((SELECT json_group_array(u.value) FROM json_each('["' || replace(replace(replace(json_extract(draft_g, '$.shovelLayer1.test'), char(92), ''), '"', ''), '*', '","') || '"]') u
      WHERE length(u.value) = 2)) END,
      'becomes', json_extract(t.value, '$.tiles.to'),
      'skill', json_extract(t.value, '$.skill'),
      'gains', json(CASE WHEN json_type(t.value, '$.imp') = 'text' AND EXISTS (SELECT 1 FROM json_each(draft_s) r
        WHERE lower(replace(json_extract(r.value, '$.skill'), ' ', '')) = lower(replace(json_extract(t.value, '$.skill'), ' ', ''))) THEN 'true' ELSE 'false' END),
      'yield', CASE json_extract(t.value, '$.counter')
        WHEN 'Chop' THEN json_extract(draft_g, '$.logs.item')
        WHEN 'Mine' THEN CASE WHEN lower(json_extract(t.value, '$.tool')) = 'mining hammer' THEN 'Mining'
          ELSE (SELECT (CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(draft_g, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(draft_g, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END) FROM json_each(draft_g, '$.mining.chunks') c
                WHERE lower(json_extract(c.value, '$.tool')) = lower(json_extract(t.value, '$.tool')) ORDER BY c.key LIMIT 1) END
      END,
      'treasure', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json('true') END
    )), '$.hitSound', json(json_extract(t.value, '$.hitSound'))), '$.successSound', json(json_extract(t.value, '$.successSound'))) AS node
    FROM json_each(draft_g, '$.tools') t
    WHERE json_extract(t.value, '$.counter') <> 'Watering' AND json_type(t.value, '$.tiles') = 'object'
      AND NOT (json_extract(t.value, '$.match') <> '=' AND EXISTS (SELECT 1 FROM json_each(draft_g, '$.tools') o
        WHERE o.key < t.key AND json_extract(o.value, '$.match') <> '='
          AND json_extract(o.value, '$.counter') = json_extract(t.value, '$.counter')
          AND lower(json_extract(o.value, '$.tiles.from')) = lower(json_extract(t.value, '$.tiles.from'))))
    ORDER BY json_extract(t.value, '$.match') <> '=', t.key) n)),
  dr_yields = json(json_patch(json_object(
      json_extract(draft_g, '$.logs.item'), json_object('kind', 'chance', 'item', json_extract(draft_g, '$.logs.item'), 'chance', json_extract(draft_g, '$.logs.chance')),
      'Mining', json_object('kind', 'ore')),
    coalesce((SELECT json_group_object((CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(draft_g, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(draft_g, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END), json_object('kind', 'chance', 'item', json_extract(c.value, '$.item'), 'chance', json_extract(c.value, '$.chance')))
      FROM (SELECT key, value FROM json_each(draft_g, '$.mining.chunks') ORDER BY key) c), '{}')));

-- Each publish that touched the gathering or the bindings, in order, with those entries.
CREATE TEMP TABLE pubs_64 (id TEXT, seq INTEGER, g TEXT, b TEXT);
INSERT INTO pubs_64
SELECT p.id, row_number() OVER (ORDER BY p.created_at, p.rowid),
  (SELECT c.value FROM json_each(p.changes) c WHERE json_extract(c.value, '$.dataset') = 'gather' AND json_extract(c.value, '$.part') = 'gathering' LIMIT 1),
  (SELECT c.value FROM json_each(p.changes) c WHERE json_extract(c.value, '$.dataset') = 'bindings' AND json_extract(c.value, '$.part') = 'skills' LIMIT 1)
FROM content_publishes p
WHERE EXISTS (SELECT 1 FROM eff_64);
DELETE FROM pubs_64 WHERE g IS NULL AND b IS NULL;

-- The gathering and the bindings each publish saw before and after it.
CREATE TEMP TABLE hist_64 (id TEXT, has_g INTEGER, has_b INTEGER, g_b TEXT, g_a TEXT, b_b TEXT, b_a TEXT);
INSERT INTO hist_64
SELECT x.id, x.g IS NOT NULL, x.b IS NOT NULL, (CASE WHEN json_type(x.gb, '$.s.data.tools') = 'array' THEN json_extract(x.gb, '$.s.data') ELSE (SELECT pack_g FROM eff_64) END), (CASE WHEN json_type(x.ga, '$.s.data.tools') = 'array' THEN json_extract(x.ga, '$.s.data') ELSE (SELECT pack_g FROM eff_64) END), (CASE WHEN json_type(x.bb, '$.s.data') = 'object' THEN json_extract(x.bb, '$.s.data') ELSE (SELECT pack_b FROM eff_64) END), (CASE WHEN json_type(x.ba, '$.s.data') = 'object' THEN json_extract(x.ba, '$.s.data') ELSE (SELECT pack_b FROM eff_64) END)
FROM (SELECT q.id, q.g, q.b,
    CASE WHEN q.g IS NULL THEN coalesce(
    (SELECT json_object('s', json(json_extract(o.g, '$.after'))) FROM pubs_64 o WHERE o.g IS NOT NULL AND o.seq < q.seq ORDER BY o.seq DESC LIMIT 1),
    (SELECT json_object('s', json(json_extract(o.g, '$.before'))) FROM pubs_64 o WHERE o.g IS NOT NULL AND o.seq > q.seq ORDER BY o.seq LIMIT 1),
    json_object('s', json_object('data', json((SELECT op_g FROM eff_64))))) ELSE json_object('s', json(json_extract(q.g, '$.before'))) END AS gb,
    CASE WHEN q.g IS NULL THEN coalesce(
    (SELECT json_object('s', json(json_extract(o.g, '$.after'))) FROM pubs_64 o WHERE o.g IS NOT NULL AND o.seq < q.seq ORDER BY o.seq DESC LIMIT 1),
    (SELECT json_object('s', json(json_extract(o.g, '$.before'))) FROM pubs_64 o WHERE o.g IS NOT NULL AND o.seq > q.seq ORDER BY o.seq LIMIT 1),
    json_object('s', json_object('data', json((SELECT op_g FROM eff_64))))) ELSE json_object('s', json(json_extract(q.g, '$.after'))) END AS ga,
    CASE WHEN q.b IS NULL THEN coalesce(
    (SELECT json_object('s', json(json_extract(o.b, '$.after'))) FROM pubs_64 o WHERE o.b IS NOT NULL AND o.seq < q.seq ORDER BY o.seq DESC LIMIT 1),
    (SELECT json_object('s', json(json_extract(o.b, '$.before'))) FROM pubs_64 o WHERE o.b IS NOT NULL AND o.seq > q.seq ORDER BY o.seq LIMIT 1),
    json_object('s', json_object('data', json((SELECT op_b FROM eff_64))))) ELSE json_object('s', json(json_extract(q.b, '$.before'))) END AS bb,
    CASE WHEN q.b IS NULL THEN coalesce(
    (SELECT json_object('s', json(json_extract(o.b, '$.after'))) FROM pubs_64 o WHERE o.b IS NOT NULL AND o.seq < q.seq ORDER BY o.seq DESC LIMIT 1),
    (SELECT json_object('s', json(json_extract(o.b, '$.before'))) FROM pubs_64 o WHERE o.b IS NOT NULL AND o.seq > q.seq ORDER BY o.seq LIMIT 1),
    json_object('s', json_object('data', json((SELECT op_b FROM eff_64))))) ELSE json_object('s', json(json_extract(q.b, '$.after'))) END AS ba
  FROM pubs_64 q) x;

CREATE TEMP TABLE hist_entries_64 (id TEXT, n INTEGER, entry TEXT);

INSERT INTO hist_entries_64
SELECT s.id, 0, json_object('dataset', 'gather', 'part', 'harvest', 'key', NULL, 'before', json(s.sb), 'after', json(s.sa))
FROM (SELECT x.id, CASE WHEN x.vb IS json((SELECT mp_harvest FROM eff_64)) THEN NULL
      ELSE json_object('op', 'set', 'data', json(x.vb), 'baseHash', NULL, 'baseData', json((SELECT mp_harvest FROM eff_64))) END AS sb, CASE WHEN x.va IS json((SELECT mp_harvest FROM eff_64)) THEN NULL
      ELSE json_object('op', 'set', 'data', json(x.va), 'baseHash', NULL, 'baseData', json((SELECT mp_harvest FROM eff_64))) END AS sa
  FROM (SELECT h.id, json((SELECT coalesce(json_group_array(json(n.node)), '[]') FROM (SELECT json_set(json_set(json_patch('{}', json_object(
      'tile', json_extract(t.value, '$.tiles.from'),
      'can', json_extract(t.value, '$.counter'),
      'tools', CASE WHEN json_extract(t.value, '$.match') = '=' THEN json_array(json_extract(t.value, '$.tool')) END,
      'under', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json((SELECT json_group_array(u.value) FROM json_each('["' || replace(replace(replace(json_extract(h.g_b, '$.shovelLayer1.test'), char(92), ''), '"', ''), '*', '","') || '"]') u
      WHERE length(u.value) = 2)) END,
      'becomes', json_extract(t.value, '$.tiles.to'),
      'skill', json_extract(t.value, '$.skill'),
      'gains', json(CASE WHEN json_type(t.value, '$.imp') = 'text' AND EXISTS (SELECT 1 FROM json_each((SELECT op_s FROM eff_64)) r
        WHERE lower(replace(json_extract(r.value, '$.skill'), ' ', '')) = lower(replace(json_extract(t.value, '$.skill'), ' ', ''))) THEN 'true' ELSE 'false' END),
      'yield', CASE json_extract(t.value, '$.counter')
        WHEN 'Chop' THEN json_extract(h.g_b, '$.logs.item')
        WHEN 'Mine' THEN CASE WHEN lower(json_extract(t.value, '$.tool')) = 'mining hammer' THEN 'Mining'
          ELSE (SELECT (CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(h.g_b, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(h.g_b, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END) FROM json_each(h.g_b, '$.mining.chunks') c
                WHERE lower(json_extract(c.value, '$.tool')) = lower(json_extract(t.value, '$.tool')) ORDER BY c.key LIMIT 1) END
      END,
      'treasure', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json('true') END
    )), '$.hitSound', json(json_extract(t.value, '$.hitSound'))), '$.successSound', json(json_extract(t.value, '$.successSound'))) AS node
    FROM json_each(h.g_b, '$.tools') t
    WHERE json_extract(t.value, '$.counter') <> 'Watering' AND json_type(t.value, '$.tiles') = 'object'
      AND NOT (json_extract(t.value, '$.match') <> '=' AND EXISTS (SELECT 1 FROM json_each(h.g_b, '$.tools') o
        WHERE o.key < t.key AND json_extract(o.value, '$.match') <> '='
          AND json_extract(o.value, '$.counter') = json_extract(t.value, '$.counter')
          AND lower(json_extract(o.value, '$.tiles.from')) = lower(json_extract(t.value, '$.tiles.from'))))
    ORDER BY json_extract(t.value, '$.match') <> '=', t.key) n)) AS vb, json((SELECT coalesce(json_group_array(json(n.node)), '[]') FROM (SELECT json_set(json_set(json_patch('{}', json_object(
      'tile', json_extract(t.value, '$.tiles.from'),
      'can', json_extract(t.value, '$.counter'),
      'tools', CASE WHEN json_extract(t.value, '$.match') = '=' THEN json_array(json_extract(t.value, '$.tool')) END,
      'under', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json((SELECT json_group_array(u.value) FROM json_each('["' || replace(replace(replace(json_extract(h.g_a, '$.shovelLayer1.test'), char(92), ''), '"', ''), '*', '","') || '"]') u
      WHERE length(u.value) = 2)) END,
      'becomes', json_extract(t.value, '$.tiles.to'),
      'skill', json_extract(t.value, '$.skill'),
      'gains', json(CASE WHEN json_type(t.value, '$.imp') = 'text' AND EXISTS (SELECT 1 FROM json_each((SELECT op_s FROM eff_64)) r
        WHERE lower(replace(json_extract(r.value, '$.skill'), ' ', '')) = lower(replace(json_extract(t.value, '$.skill'), ' ', ''))) THEN 'true' ELSE 'false' END),
      'yield', CASE json_extract(t.value, '$.counter')
        WHEN 'Chop' THEN json_extract(h.g_a, '$.logs.item')
        WHEN 'Mine' THEN CASE WHEN lower(json_extract(t.value, '$.tool')) = 'mining hammer' THEN 'Mining'
          ELSE (SELECT (CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(h.g_a, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(h.g_a, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END) FROM json_each(h.g_a, '$.mining.chunks') c
                WHERE lower(json_extract(c.value, '$.tool')) = lower(json_extract(t.value, '$.tool')) ORDER BY c.key LIMIT 1) END
      END,
      'treasure', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json('true') END
    )), '$.hitSound', json(json_extract(t.value, '$.hitSound'))), '$.successSound', json(json_extract(t.value, '$.successSound'))) AS node
    FROM json_each(h.g_a, '$.tools') t
    WHERE json_extract(t.value, '$.counter') <> 'Watering' AND json_type(t.value, '$.tiles') = 'object'
      AND NOT (json_extract(t.value, '$.match') <> '=' AND EXISTS (SELECT 1 FROM json_each(h.g_a, '$.tools') o
        WHERE o.key < t.key AND json_extract(o.value, '$.match') <> '='
          AND json_extract(o.value, '$.counter') = json_extract(t.value, '$.counter')
          AND lower(json_extract(o.value, '$.tiles.from')) = lower(json_extract(t.value, '$.tiles.from'))))
    ORDER BY json_extract(t.value, '$.match') <> '=', t.key) n)) AS va FROM hist_64 h WHERE h.has_g) x) s
WHERE s.sb IS NOT s.sa
  AND NOT EXISTS (SELECT 1 FROM content_publishes p, json_each(p.changes) c WHERE p.id = s.id
    AND json_extract(c.value, '$.dataset') = 'gather' AND json_extract(c.value, '$.part') = 'harvest');

INSERT INTO hist_entries_64
SELECT s.id, 1, json_object('dataset', 'gather', 'part', 'yields', 'key', NULL, 'before', json(s.sb), 'after', json(s.sa))
FROM (SELECT x.id, CASE WHEN x.vb IS json((SELECT mp_yields FROM eff_64)) THEN NULL
      ELSE json_object('op', 'set', 'data', json(x.vb), 'baseHash', NULL, 'baseData', json((SELECT mp_yields FROM eff_64))) END AS sb, CASE WHEN x.va IS json((SELECT mp_yields FROM eff_64)) THEN NULL
      ELSE json_object('op', 'set', 'data', json(x.va), 'baseHash', NULL, 'baseData', json((SELECT mp_yields FROM eff_64))) END AS sa
  FROM (SELECT h.id, json(json_patch(json_object(
      json_extract(h.g_b, '$.logs.item'), json_object('kind', 'chance', 'item', json_extract(h.g_b, '$.logs.item'), 'chance', json_extract(h.g_b, '$.logs.chance')),
      'Mining', json_object('kind', 'ore')),
    coalesce((SELECT json_group_object((CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(h.g_b, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(h.g_b, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END), json_object('kind', 'chance', 'item', json_extract(c.value, '$.item'), 'chance', json_extract(c.value, '$.chance')))
      FROM (SELECT key, value FROM json_each(h.g_b, '$.mining.chunks') ORDER BY key) c), '{}'))) AS vb, json(json_patch(json_object(
      json_extract(h.g_a, '$.logs.item'), json_object('kind', 'chance', 'item', json_extract(h.g_a, '$.logs.item'), 'chance', json_extract(h.g_a, '$.logs.chance')),
      'Mining', json_object('kind', 'ore')),
    coalesce((SELECT json_group_object((CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(h.g_a, '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(h.g_a, '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END), json_object('kind', 'chance', 'item', json_extract(c.value, '$.item'), 'chance', json_extract(c.value, '$.chance')))
      FROM (SELECT key, value FROM json_each(h.g_a, '$.mining.chunks') ORDER BY key) c), '{}'))) AS va FROM hist_64 h WHERE h.has_g) x) s
WHERE s.sb IS NOT s.sa
  AND NOT EXISTS (SELECT 1 FROM content_publishes p, json_each(p.changes) c WHERE p.id = s.id
    AND json_extract(c.value, '$.dataset') = 'gather' AND json_extract(c.value, '$.part') = 'yields');

INSERT INTO hist_entries_64
SELECT s.id, 2, json_object('dataset', 'itemRules', 'part', 'tools', 'key', NULL, 'before', json(s.sb), 'after', json(s.sa))
FROM (SELECT x.id, CASE WHEN x.vb IS json((SELECT mp_tools FROM eff_64)) THEN NULL
      ELSE json_object('op', 'set', 'data', json(x.vb), 'baseHash', NULL, 'baseData', json((SELECT mp_tools FROM eff_64))) END AS sb, CASE WHEN x.va IS json((SELECT mp_tools FROM eff_64)) THEN NULL
      ELSE json_object('op', 'set', 'data', json(x.va), 'baseHash', NULL, 'baseData', json((SELECT mp_tools FROM eff_64))) END AS sa
  FROM (SELECT h.id, json(json_insert(CASE WHEN json_type(h.b_b, '$.mining') = 'text' THEN json_insert(CASE WHEN json_type(h.b_b, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(h.g_b, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(h.g_b, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(h.g_b, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(h.g_b, '$.fishing.tool'), 'can', 'Fish')) END, '$[#]', json('{"match":"contains","pattern":"Mining","ladder":"mining"}')) ELSE CASE WHEN json_type(h.b_b, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(h.g_b, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(h.g_b, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(h.g_b, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(h.g_b, '$.fishing.tool'), 'can', 'Fish')) END END, '$[#]', json('{"match":"contains","pattern":"Fishing","ladder":"fishing"}'))) AS vb, json(json_insert(CASE WHEN json_type(h.b_a, '$.mining') = 'text' THEN json_insert(CASE WHEN json_type(h.b_a, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(h.g_a, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(h.g_a, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(h.g_a, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(h.g_a, '$.fishing.tool'), 'can', 'Fish')) END, '$[#]', json('{"match":"contains","pattern":"Mining","ladder":"mining"}')) ELSE CASE WHEN json_type(h.b_a, '$.axeFighting') = 'text' THEN json_insert(json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(h.g_a, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(h.g_a, '$.fishing.tool'), 'can', 'Fish')), '$[#]', json('{"match":"contains","pattern":"Axe","ladder":"axe"}')) ELSE json_insert((SELECT coalesce(json_group_array(json(r.row)), '[]') FROM (SELECT json_object(
      'match', CASE WHEN json_extract(t.value, '$.match') = 'contains' THEN 'contains' ELSE 'exact' END,
      'pattern', json_extract(t.value, '$.tool'),
      'can', CASE json_extract(t.value, '$.counter') WHEN 'Watering' THEN 'Water' ELSE json_extract(t.value, '$.counter') END) AS row
    FROM json_each(h.g_a, '$.tools') t ORDER BY t.key) r), '$[#]', json_object('match', 'contains', 'pattern', json_extract(h.g_a, '$.fishing.tool'), 'can', 'Fish')) END END, '$[#]', json('{"match":"contains","pattern":"Fishing","ladder":"fishing"}'))) AS va FROM hist_64 h WHERE 1) x) s
WHERE s.sb IS NOT s.sa
  AND NOT EXISTS (SELECT 1 FROM content_publishes p, json_each(p.changes) c WHERE p.id = s.id
    AND json_extract(c.value, '$.dataset') = 'itemRules' AND json_extract(c.value, '$.part') = 'tools');

INSERT INTO hist_entries_64
SELECT s.id, 3, json_object('dataset', 'itemRules', 'part', 'ladders', 'key', NULL, 'before', json(s.sb), 'after', json(s.sa))
FROM (SELECT x.id, CASE WHEN x.vb IS json((SELECT mp_ladders FROM eff_64)) THEN NULL
      ELSE json_object('op', 'set', 'data', json(x.vb), 'baseHash', NULL, 'baseData', json((SELECT mp_ladders FROM eff_64))) END AS sb, CASE WHEN x.va IS json((SELECT mp_ladders FROM eff_64)) THEN NULL
      ELSE json_object('op', 'set', 'data', json(x.va), 'baseHash', NULL, 'baseData', json((SELECT mp_ladders FROM eff_64))) END AS sa
  FROM (SELECT h.id, json(json_patch('{}', json_object(
      'axe', CASE WHEN json_type(h.b_b, '$.axeFighting') = 'text' THEN json_object('skill', json_extract(h.b_b, '$.axeFighting'), 'steps', json('[{"below":10,"delay":25},{"below":20,"delay":22},{"below":30,"delay":21},{"below":40,"delay":20},{"below":50,"delay":19},{"below":60,"delay":18},{"below":70,"delay":17},{"below":80,"delay":16},{"below":90,"delay":15}]')) END,
      'mining', CASE WHEN json_type(h.b_b, '$.mining') = 'text' THEN json_object('skill', json_extract(h.b_b, '$.mining'), 'steps', json('[{"below":10,"delay":15},{"below":20,"delay":14},{"below":30,"delay":13},{"below":40,"delay":12},{"below":50,"delay":11},{"below":60,"delay":10},{"below":70,"delay":9},{"below":80,"delay":8},{"delay":7}]')) END,
      'fishing', json_object('steps', json_array(json_object('delay', min(max(json_extract(h.g_b, '$.fishing.atDelay'), 1), 1000))), 'gearSpeedUp', json('true'))))) AS vb, json(json_patch('{}', json_object(
      'axe', CASE WHEN json_type(h.b_a, '$.axeFighting') = 'text' THEN json_object('skill', json_extract(h.b_a, '$.axeFighting'), 'steps', json('[{"below":10,"delay":25},{"below":20,"delay":22},{"below":30,"delay":21},{"below":40,"delay":20},{"below":50,"delay":19},{"below":60,"delay":18},{"below":70,"delay":17},{"below":80,"delay":16},{"below":90,"delay":15}]')) END,
      'mining', CASE WHEN json_type(h.b_a, '$.mining') = 'text' THEN json_object('skill', json_extract(h.b_a, '$.mining'), 'steps', json('[{"below":10,"delay":15},{"below":20,"delay":14},{"below":30,"delay":13},{"below":40,"delay":12},{"below":50,"delay":11},{"below":60,"delay":10},{"below":70,"delay":9},{"below":80,"delay":8},{"delay":7}]')) END,
      'fishing', json_object('steps', json_array(json_object('delay', min(max(json_extract(h.g_a, '$.fishing.atDelay'), 1), 1000))), 'gearSpeedUp', json('true'))))) AS va FROM hist_64 h WHERE 1) x) s
WHERE s.sb IS NOT s.sa
  AND NOT EXISTS (SELECT 1 FROM content_publishes p, json_each(p.changes) c WHERE p.id = s.id
    AND json_extract(c.value, '$.dataset') = 'itemRules' AND json_extract(c.value, '$.part') = 'ladders');

UPDATE content_packs
SET data = json_set(data,
  '$.data."item-rules".tools', json((SELECT mp_tools FROM eff_64)),
  '$.data."item-rules".ladders', json((SELECT mp_ladders FROM eff_64)),
  '$.data."item-rules".requires', json(coalesce(json_extract(data, '$.data."item-rules".requires'), '[]')))
WHERE EXISTS (SELECT 1 FROM eff_64) AND source = 'imported' AND json_type(data, '$.data."item-rules"') = 'object'
  AND json_type(data, '$.data."item-rules".tools') IS NULL;

UPDATE content_packs
SET data = json_set(data,
  '$.data.gather.harvest', json((SELECT coalesce(json_group_array(json(n.node)), '[]') FROM (SELECT json_set(json_set(json_patch('{}', json_object(
      'tile', json_extract(t.value, '$.tiles.from'),
      'can', json_extract(t.value, '$.counter'),
      'tools', CASE WHEN json_extract(t.value, '$.match') = '=' THEN json_array(json_extract(t.value, '$.tool')) END,
      'under', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json((SELECT json_group_array(u.value) FROM json_each('["' || replace(replace(replace(json_extract(json_extract(data, '$.data.gather.gathering'), '$.shovelLayer1.test'), char(92), ''), '"', ''), '*', '","') || '"]') u
      WHERE length(u.value) = 2)) END,
      'becomes', json_extract(t.value, '$.tiles.to'),
      'skill', json_extract(t.value, '$.skill'),
      'gains', json(CASE WHEN json_type(t.value, '$.imp') = 'text' AND EXISTS (SELECT 1 FROM json_each(coalesce(json_extract(data, '$.data.gather.skillGain'), '[]')) r
        WHERE lower(replace(json_extract(r.value, '$.skill'), ' ', '')) = lower(replace(json_extract(t.value, '$.skill'), ' ', ''))) THEN 'true' ELSE 'false' END),
      'yield', CASE json_extract(t.value, '$.counter')
        WHEN 'Chop' THEN json_extract(json_extract(data, '$.data.gather.gathering'), '$.logs.item')
        WHEN 'Mine' THEN CASE WHEN lower(json_extract(t.value, '$.tool')) = 'mining hammer' THEN 'Mining'
          ELSE (SELECT (CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(json_extract(data, '$.data.gather.gathering'), '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(json_extract(data, '$.data.gather.gathering'), '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END) FROM json_each(json_extract(data, '$.data.gather.gathering'), '$.mining.chunks') c
                WHERE lower(json_extract(c.value, '$.tool')) = lower(json_extract(t.value, '$.tool')) ORDER BY c.key LIMIT 1) END
      END,
      'treasure', CASE WHEN json_extract(t.value, '$.counter') = 'Dig' THEN json('true') END
    )), '$.hitSound', json(json_extract(t.value, '$.hitSound'))), '$.successSound', json(json_extract(t.value, '$.successSound'))) AS node
    FROM json_each(json_extract(data, '$.data.gather.gathering'), '$.tools') t
    WHERE json_extract(t.value, '$.counter') <> 'Watering' AND json_type(t.value, '$.tiles') = 'object'
      AND NOT (json_extract(t.value, '$.match') <> '=' AND EXISTS (SELECT 1 FROM json_each(json_extract(data, '$.data.gather.gathering'), '$.tools') o
        WHERE o.key < t.key AND json_extract(o.value, '$.match') <> '='
          AND json_extract(o.value, '$.counter') = json_extract(t.value, '$.counter')
          AND lower(json_extract(o.value, '$.tiles.from')) = lower(json_extract(t.value, '$.tiles.from'))))
    ORDER BY json_extract(t.value, '$.match') <> '=', t.key) n)),
  '$.data.gather.yields', json(json_patch(json_object(
      json_extract(json_extract(data, '$.data.gather.gathering'), '$.logs.item'), json_object('kind', 'chance', 'item', json_extract(json_extract(data, '$.data.gather.gathering'), '$.logs.item'), 'chance', json_extract(json_extract(data, '$.data.gather.gathering'), '$.logs.chance')),
      'Mining', json_object('kind', 'ore')),
    coalesce((SELECT json_group_object((CASE WHEN lower(json_extract(c.value, '$.item')) IN (lower(json_extract(json_extract(data, '$.data.gather.gathering'), '$.logs.item')), 'mining')
      OR EXISTS (SELECT 1 FROM json_each(json_extract(data, '$.data.gather.gathering'), '$.mining.chunks') o
        WHERE o.key <> c.key AND lower(json_extract(o.value, '$.item')) = lower(json_extract(c.value, '$.item')))
      THEN json_extract(c.value, '$.item') || ' (' || json_extract(c.value, '$.tool') || ')' ELSE json_extract(c.value, '$.item') END), json_object('kind', 'chance', 'item', json_extract(c.value, '$.item'), 'chance', json_extract(c.value, '$.chance')))
      FROM (SELECT key, value FROM json_each(json_extract(data, '$.data.gather.gathering'), '$.mining.chunks') ORDER BY key) c), '{}'))),
  '$.data.gather.gathering', json(json_set(json_remove(json_extract(data, '$.data.gather.gathering'), '$.tools', '$.logs', '$.shovelLayer1', '$.mining.chunks', '$.fishing.tool', '$.fishing.match', '$.fishing.atDelay'),
      '$.farming.wateringSkill', coalesce((SELECT json_extract(t.value, '$.skill') FROM json_each(json_extract(data, '$.data.gather.gathering'), '$.tools') t
      WHERE json_extract(t.value, '$.counter') = 'Watering' ORDER BY t.key LIMIT 1), 'Farming'))))
WHERE EXISTS (SELECT 1 FROM eff_64) AND source = 'imported' AND json_type(data, '$.data.gather.gathering.tools') = 'array';

UPDATE content_packs
SET data = json_set(data, '$.data.bindings.skills', json(json_remove(json_extract(data, '$.data.bindings.skills'), '$.axeFighting', '$.mining')))
WHERE EXISTS (SELECT 1 FROM eff_64) AND source = 'imported' AND json_type(data, '$.data.bindings.skills') = 'object';

INSERT INTO content_rows (dataset, part, row_key, op, data, base_hash, base_data, seq, updated_by, updated_at)
SELECT 'itemRules', 'tools', '', 'set', op_tools, NULL, mp_tools,
  (SELECT coalesce(max(seq), 0) + 1 FROM content_rows),
  coalesce((SELECT updated_by FROM content_rows WHERE ((dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills')) ORDER BY dataset DESC LIMIT 1), 'system'),
  coalesce((SELECT updated_at FROM content_rows WHERE ((dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills')) ORDER BY dataset DESC LIMIT 1), '2026-11-23T00:00:00.000Z')
FROM eff_64
WHERE op_tools IS NOT mp_tools
  AND NOT EXISTS (SELECT 1 FROM content_rows WHERE dataset = 'itemRules' AND part = 'tools');

INSERT INTO content_rows (dataset, part, row_key, op, data, base_hash, base_data, seq, updated_by, updated_at)
SELECT 'itemRules', 'ladders', '', 'set', op_ladders, NULL, mp_ladders,
  (SELECT coalesce(max(seq), 0) + 1 FROM content_rows),
  coalesce((SELECT updated_by FROM content_rows WHERE ((dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills')) ORDER BY dataset DESC LIMIT 1), 'system'),
  coalesce((SELECT updated_at FROM content_rows WHERE ((dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills')) ORDER BY dataset DESC LIMIT 1), '2026-11-23T00:00:00.000Z')
FROM eff_64
