INSERT INTO content_rows (dataset, part, row_key, op, data, base_hash, base_data, seq, updated_by, updated_at)
SELECT 'gather', 'yields', '', 'set', op_yields, NULL, mp_yields,
  (SELECT coalesce(max(seq), 0) + 1 FROM content_rows),
  coalesce((SELECT updated_by FROM content_rows WHERE ((dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills')) ORDER BY dataset DESC LIMIT 1), 'system'),
  coalesce((SELECT updated_at FROM content_rows WHERE ((dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills')) ORDER BY dataset DESC LIMIT 1), '2026-11-23T00:00:00.000Z')
FROM eff_64
WHERE op_yields IS NOT mp_yields
  AND NOT EXISTS (SELECT 1 FROM content_rows WHERE dataset = 'gather' AND part = 'yields');

UPDATE content_rows SET data = json(json_set(json_remove(data, '$.tools', '$.logs', '$.shovelLayer1', '$.mining.chunks', '$.fishing.tool', '$.fishing.match', '$.fishing.atDelay'),
      '$.farming.wateringSkill', coalesce((SELECT json_extract(t.value, '$.skill') FROM json_each(data, '$.tools') t
      WHERE json_extract(t.value, '$.counter') = 'Watering' ORDER BY t.key LIMIT 1), 'Farming')))
WHERE EXISTS (SELECT 1 FROM eff_64) AND dataset = 'gather' AND part = 'gathering' AND op = 'set' AND json_type(data, '$.tools') = 'array';
UPDATE content_rows SET data = json(json_remove(data, '$.axeFighting', '$.mining'))
WHERE EXISTS (SELECT 1 FROM eff_64) AND dataset = 'bindings' AND part = 'skills' AND op = 'set' AND json_type(data) = 'object';

INSERT INTO content_draft (dataset, part, row_key, op, data, author_account_id, author, updated_at)
SELECT 'itemRules', 'tools', '',
  CASE WHEN dr_tools IS mp_tools THEN 'revert' ELSE 'set' END,
  CASE WHEN dr_tools IS mp_tools THEN NULL ELSE dr_tools END,
  (SELECT author_account_id FROM content_draft WHERE ((dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills')) ORDER BY dataset DESC LIMIT 1), (SELECT author FROM content_draft WHERE ((dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills')) ORDER BY dataset DESC LIMIT 1), (SELECT updated_at FROM content_draft WHERE ((dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills')) ORDER BY dataset DESC LIMIT 1)
FROM eff_64
WHERE dr_tools IS NOT op_tools
  AND EXISTS (SELECT 1 FROM content_draft WHERE (dataset = 'gather' AND part = 'gathering') OR (dataset = 'bindings' AND part = 'skills'))
  AND NOT EXISTS (SELECT 1 FROM content_draft WHERE dataset = 'itemRules' AND part = 'tools');

INSERT INTO content_draft (dataset, part, row_key, op, data, author_account_id, author, updated_at)
