  AND NOT EXISTS (SELECT 1 FROM content_draft WHERE dataset = 'itemRules' AND part = 'ladders');

INSERT INTO content_draft (dataset, part, row_key, op, data, author_account_id, author, updated_at)
SELECT 'gather', 'harvest', '',
