UPDATE content_draft SET data = json(json_set(json_remove(data, '$.tools', '$.logs', '$.shovelLayer1', '$.mining.chunks', '$.fishing.tool', '$.fishing.match', '$.fishing.atDelay'),
      '$.farming.wateringSkill', coalesce((SELECT json_extract(t.value, '$.skill') FROM json_each(data, '$.tools') t
      WHERE json_extract(t.value, '$.counter') = 'Watering' ORDER BY t.key LIMIT 1), 'Farming')))
WHERE EXISTS (SELECT 1 FROM eff_64) AND dataset = 'gather' AND part = 'gathering' AND op = 'set' AND json_type(data, '$.tools') = 'array';
UPDATE content_draft SET data = json(json_remove(data, '$.axeFighting', '$.mining'))
WHERE EXISTS (SELECT 1 FROM eff_64) AND dataset = 'bindings' AND part = 'skills' AND op = 'set' AND json_type(data) = 'object';

UPDATE content_publishes
SET changes = (
  SELECT json_group_array(json(CASE
    WHEN json_extract(c.value, '$.dataset') = 'gather' AND json_extract(c.value, '$.part') = 'gathering'
      AND json_type(c.value, '$.before.data') = 'object'
    THEN json_set(c.value, '$.before.data', json(CASE WHEN json_type(json_extract(c.value, '$.before.data'), '$.tools') = 'array' THEN json_set(json_remove(json_extract(c.value, '$.before.data'), '$.tools', '$.logs', '$.shovelLayer1', '$.mining.chunks', '$.fishing.tool', '$.fishing.match', '$.fishing.atDelay'),
      '$.farming.wateringSkill', coalesce((SELECT json_extract(t.value, '$.skill') FROM json_each(json_extract(c.value, '$.before.data'), '$.tools') t
      WHERE json_extract(t.value, '$.counter') = 'Watering' ORDER BY t.key LIMIT 1), 'Farming')) ELSE json_extract(c.value, '$.before.data') END))
    ELSE c.value
  END))
  FROM (SELECT key, value FROM json_each(content_publishes.changes) ORDER BY key) c
)
WHERE EXISTS (SELECT 1 FROM eff_64) AND EXISTS (
  SELECT 1 FROM json_each(content_publishes.changes) c
  WHERE json_extract(c.value, '$.dataset') = 'gather' AND json_extract(c.value, '$.part') = 'gathering'
);
UPDATE content_publishes
SET changes = (
  SELECT json_group_array(json(CASE
    WHEN json_extract(c.value, '$.dataset') = 'gather' AND json_extract(c.value, '$.part') = 'gathering'
      AND json_type(c.value, '$.after.data') = 'object'
    THEN json_set(c.value, '$.after.data', json(CASE WHEN json_type(json_extract(c.value, '$.after.data'), '$.tools') = 'array' THEN json_set(json_remove(json_extract(c.value, '$.after.data'), '$.tools', '$.logs', '$.shovelLayer1', '$.mining.chunks', '$.fishing.tool', '$.fishing.match', '$.fishing.atDelay'),
      '$.farming.wateringSkill', coalesce((SELECT json_extract(t.value, '$.skill') FROM json_each(json_extract(c.value, '$.after.data'), '$.tools') t
      WHERE json_extract(t.value, '$.counter') = 'Watering' ORDER BY t.key LIMIT 1), 'Farming')) ELSE json_extract(c.value, '$.after.data') END))
    ELSE c.value
  END))
  FROM (SELECT key, value FROM json_each(content_publishes.changes) ORDER BY key) c
)
WHERE EXISTS (SELECT 1 FROM eff_64) AND EXISTS (
  SELECT 1 FROM json_each(content_publishes.changes) c
  WHERE json_extract(c.value, '$.dataset') = 'gather' AND json_extract(c.value, '$.part') = 'gathering'
);
UPDATE content_publishes
SET changes = (
  SELECT json_group_array(json(CASE
    WHEN json_extract(c.value, '$.dataset') = 'bindings' AND json_extract(c.value, '$.part') = 'skills'
      AND json_type(c.value, '$.before.data') = 'object'
    THEN json_set(c.value, '$.before.data', json(json_remove(json_extract(c.value, '$.before.data'), '$.axeFighting', '$.mining')))
    ELSE c.value
  END))
  FROM (SELECT key, value FROM json_each(content_publishes.changes) ORDER BY key) c
)
WHERE EXISTS (SELECT 1 FROM eff_64) AND EXISTS (
  SELECT 1 FROM json_each(content_publishes.changes) c
  WHERE json_extract(c.value, '$.dataset') = 'bindings' AND json_extract(c.value, '$.part') = 'skills'
);
UPDATE content_publishes
SET changes = (
  SELECT json_group_array(json(CASE
    WHEN json_extract(c.value, '$.dataset') = 'bindings' AND json_extract(c.value, '$.part') = 'skills'
      AND json_type(c.value, '$.after.data') = 'object'
    THEN json_set(c.value, '$.after.data', json(json_remove(json_extract(c.value, '$.after.data'), '$.axeFighting', '$.mining')))
    ELSE c.value
  END))
  FROM (SELECT key, value FROM json_each(content_publishes.changes) ORDER BY key) c
)
WHERE EXISTS (SELECT 1 FROM eff_64) AND EXISTS (
  SELECT 1 FROM json_each(content_publishes.changes) c
  WHERE json_extract(c.value, '$.dataset') = 'bindings' AND json_extract(c.value, '$.part') = 'skills'
);

UPDATE content_publishes
SET changes = (
  SELECT json_group_array(json(v)) FROM (
    SELECT value AS v, key AS k FROM json_each(content_publishes.changes)
    UNION ALL
    SELECT entry, 1000000 + n FROM hist_entries_64 WHERE hist_entries_64.id = content_publishes.id
    ORDER BY k)
)
WHERE id IN (SELECT id FROM hist_entries_64);

